6	
7		"github.com/cocosolocoder/signalroom/internal/metrics"
8	)
9	
10	// metricsLogName is the append-only batch log for metric samples. It sits
11	// next to events.log in the locked data directory and uses the same
12	// length-prefixed, CRC-checked frame layout, so the durability and recovery
13	// rules are identical: fsync before acknowledging, trim only a torn tail,
14	// and refuse to start on any other corruption.
15	const metricsLogName = "metrics.log"
16	
17	// MetricsLog is the concurrency-safe durable writer for metric batches. It is
18	// independent from both the event and incident logs: a metric write failure
19	// poisons only metric handling, leaving events and incidents available.
20	type MetricsLog struct {
21		*frameLog
22	}
23	
24	// OpenMetricsLog opens (creating if absent) the metrics log inside an
25	// already-locked data directory, replays its batches, and truncates at most
26	// one incomplete trailing frame. A corrupt frame in the middle, a complete
27	// frame containing illegal data, or two complete records that clash — the
28	// same sample id with different normalized content, or two different ids on
29	// one series at one sampling instant — is fatal and leaves the file
30	// untouched, any torn tail included. Call it only after Open has acquired the
31	// directory lock.
32	func OpenMetricsLog(dir string) (*MetricsLog, [][]metrics.Sample, error) {
33		if dir == "" {
34			return nil, nil, fmt.Errorf("data directory is required")
35		}
36		base, batches, err := openFrameLog(dir, metricsLogName, "metrics", "metric batch", decodeMetricBatch, checkMetricConflicts)
37		if err != nil {
38			return nil, nil, err
39		}
40		return &MetricsLog{frameLog: base}, batches, nil
41	}
42	
43	// checkMetricConflicts rejects a recovered log whose complete, valid records
44	// contradict one another: one sample id carrying different normalized
45	// content, or two different ids occupying the same series (service, metric
46	// name, full label set) at the same sampling instant. It replays every
47	// complete batch into a fresh store, reusing the store's own recovery rules,
48	// so the comparison matches what serving would apply: identical retries
49	// collapse to one sample, timezone/label-order/trim spelling and 1 vs 1.0 do
50	// not clash, while a one-nanosecond move or a differing label set do. The
51	// clash may sit inside one batch or span several; that each batch reads on
52	// its own does not make the history legal. It runs before any torn-tail
53	// truncation, so a conflicting log keeps every byte it had before startup.
54	func checkMetricConflicts(batches [][]metrics.Sample) error {
55		recovered := metrics.NewStore()
56		for _, batch := range batches {
57			for _, sample := range batch {
58				if err := recovered.Load(sample); err != nil {
59					return fmt.Errorf("metrics history contains a sample conflict: %w", err)
60				}
61			}
62		}
63		return nil
64	}
65	
66	// decodeMetricBatch decodes one frame payload into a validated, normalized
67	// metric batch. An empty batch or an invalid sample is rejected as
68	// corruption.
69	func decodeMetricBatch(payload []byte) ([]metrics.Sample, error) {
70		batch, err := metrics.DecodeBatch(payload)
71		if err != nil {
72			return nil, err
73		}
74		if len(batch) == 0 {
75			return nil, errors.New("empty metric batch frame")
76		}
77		for i := range batch {
78			normalized, err := metrics.Normalize(batch[i])
79			if err != nil {
80				return nil, err
81			}
82			batch[i] = normalized
83		}
84		return batch, nil
85	}
86	
87	// Append durably writes one batch: the frame is written and fsynced before the
88	// call returns. Any write or sync failure poisons the log so that this call
89	// and every later one fail until restart.
90	func (l *MetricsLog) Append(batch []metrics.Sample) error {
91		payload, err := metrics.MarshalBatch(batch)
92		if err != nil {
93			return fmt.Errorf("encode metric batch: %w", err)
94		}
95		return l.appendFrame(payload)
96	}
