177			dataDir := t.TempDir()
178			first := startServer(t, dataDir)
179			postIncident(t, first, `{"id":"INC-8","title":"t","service":"gateway","operator":"Alice"}`)
180			if s, _ := postIncidentAction(t, first, "INC-8",
181				`{"action_id":"p1","operator":"alice","expected_version":1,"action":"add_participant","participant":"bob"}`); s != http.StatusOK {
182				t.Fatalf("add bob status %d", s)
183			}
