187	
188			// Complete, well-formed record: fresh action id, sequential version,
189			// legal in every respect except that carol never joined.
190			bad := incidents.NewActionRecord(incidents.Request{
191				IncidentID: "INC-8", ActionID: "o1", Operator: "alice",
192				ExpectedVersion: 2, Type: incidents.ActionAssignOwner, Content: "carol",
