226			bad := incidents.NewActionRecord(incidents.Request{
227				IncidentID: "INC-8", ActionID: "o1", Operator: "alice",
228				ExpectedVersion: 3, Type: incidents.ActionAssignOwner, Content: "bob",
229			}, stamp(2))
230			follow := incidents.NewActionRecord(incidents.Request{
231				IncidentID: "INC-8", ActionID: "n1", Operator: "alice",
232				ExpectedVersion: 4, Type: incidents.ActionNote, Content: "after the bad handover",
233			}, stamp(3))
