241	// expectServeFailsOnIncidentLog runs serve against dataDir, requires a
242	// non-zero exit without a readiness line, checks that the startup error
243	// contains every want fragment, and verifies the incident log file is
244	// byte-for-byte unchanged.
245	func expectServeFailsOnIncidentLog(t *testing.T, dataDir string, wantBytes []byte, path string, want ...string) {
