	if err != nil {
		t.Fatal(err)
	}
	if len(after) != len(corrupt) {
		t.Fatal("failed startup must not truncate or modify the corrupt log")
	}
}

func TestIncidentLogPoisonedAfterWriteFailure(t *testing.T) {
	dir := t.TempDir()
	base := time.Date(2026, 10, 1, 9, 0, 0, 0, time.UTC)
